import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500; // within the 250 ms – 2 s window
const MAX_ATTEMPTS = 3;
const HEARTBEAT_MS = 1_000;
const IDLE_MS = 100;

const db = openDatabase();
let stopping = false;

const claimNext = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
   WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1)
   RETURNING *`,
);
const setProgress = db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?');
const setCompleted = db.prepare(`UPDATE jobs SET status = 'completed', output = ?, completed = steps, error = NULL, updated_at = ? WHERE seq = ?`);
const setFailed = db.prepare(`UPDATE jobs SET status = 'failed', output = NULL, error = 'transient failure', updated_at = ? WHERE seq = ?`);
const requeue = db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE seq = ?`);
// An attempt interrupted by a crash never finished, so it is rolled back and processed again.
const recoverRunning = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`,
);
const beat = db.prepare(`INSERT INTO heartbeat (name, at_ms) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms`);

const iso = () => new Date().toISOString();

function heartbeat(): void {
  try {
    beat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

async function runAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, if n <= failAttempts.
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts >= MAX_ATTEMPTS) {
      setFailed.run(iso(), job.seq);
      console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    } else {
      requeue.run(Date.now() + RETRY_DELAY_MS, iso(), job.seq);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // left 'running'; recovered on the next start
    setProgress.run(step, iso(), job.seq);
  }
  setCompleted.run(job.input.toUpperCase(), iso(), job.seq);
  console.log(`job ${job.id} completed`);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

recoverRunning.run(iso());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext.get(iso(), Date.now()) as unknown as JobRow | undefined;
    if (job) await runAttempt(job);
    else await sleep(IDLE_MS);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(500);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');
process.exit(0);

