1	import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
2	import { readFileSync } from 'node:fs';
3	import { randomUUID } from 'node:crypto';
4	import { openDatabase, type JobRow } from './db.ts';
5	
6	const WORKER_STALE_MS = 3_000;
7	const MAX_BODY_BYTES = 64 * 1024;
8	const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
9	const FIELD_NAMES = ['input', 'steps', 'failAttempts'];
10	
11	interface FieldError {
12	  field: string;
13	  message: string;
14	}
15	
16	interface JobInput {
17	  input: string;
18	  steps: number;
19	  failAttempts: number;
20	}
21	
22	const db = openDatabase();
23	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
24	
25	const insertJob = db.prepare(
26	  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, fingerprint, available_at, created_at, updated_at)
27	   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
28	);
29	const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
30	const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
31	const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
32	const selectHeartbeat = db.prepare("SELECT at_ms FROM heartbeat WHERE name = 'worker'");
33	
34	function toJob(row: JobRow) {
35	  return {
36	    id: row.id,
37	    status: row.status,
38	    input: row.input,
39	    steps: row.steps,
40	    failAttempts: row.fail_attempts,
41	    attempts: row.attempts,
42	    progress: { completed: row.completed, total: row.steps },
43	    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
44	    error: row.status === 'failed' ? row.error : null,
45	    createdAt: row.created_at,
46	    updatedAt: row.updated_at,
47	  };
48	}
49	
50	function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
51	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
52	  res.end(JSON.stringify(body));
53	}
54	
55	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
56	  const error: Record<string, unknown> = { code, message };
57	  if (fields) error.fields = fields;
58	  send(res, status, { error }, headers);
59	}
60	
61	function intField(obj: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, errors: FieldError[]): number {
62	  if (!Object.hasOwn(obj, name)) return fallback;
63	  const value = obj[name];
64	  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
65	    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
66	    return fallback;
67	  }
68	  return value;
69	}
70	
71	/** Validates a parsed request body. Returns undefined when the body is not an object (an error is recorded). */
72	function validateBody(raw: unknown, errors: FieldError[]): JobInput | undefined {
73	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
74	    errors.push({ field: 'body', message: 'must be a JSON object' });
75	    return undefined;
76	  }
77	  const obj = raw as Record<string, unknown>;
78	  for (const key of Object.keys(obj)) {
79	    if (!FIELD_NAMES.includes(key)) errors.push({ field: key, message: 'is not a recognised field' });
80	  }
81	  let input = '';
82	  const rawInput = obj.input;
83	  if (typeof rawInput !== 'string') errors.push({ field: 'input', message: 'is required and must be a string' });
84	  else if (rawInput.length < 1 || rawInput.length > 1000) errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
85	  else if (rawInput.trim() === '') errors.push({ field: 'input', message: 'must not be only whitespace' });
86	  else input = rawInput;
87	  const steps = intField(obj, 'steps', 1, 20, 5, errors);
88	  const failAttempts = intField(obj, 'failAttempts', 0, 5, 0, errors);
89	  return { input, steps, failAttempts };
90	}
91	
92	function readBody(req: IncomingMessage): Promise<string | undefined> {
93	  return new Promise((resolve, reject) => {
94	    const chunks: Buffer[] = [];
95	    let size = 0;
96	    let tooLarge = false;
97	    req.on('data', (chunk: Buffer) => {
98	      size += chunk.length;
99	      if (size > MAX_BODY_BYTES) tooLarge = true;
100	      else chunks.push(chunk);
101	    });
102	    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
103	    req.on('error', reject);
104	  });
105	}
106	
107	async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
108	  const errors: FieldError[] = [];
109	  const text = await readBody(req);
110	
111	  const mediaType = req.headers['content-type']?.split(';')[0]?.trim().toLowerCase();
112	  let values: JobInput | undefined;
113	  if (mediaType !== 'application/json') {
114	    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
115	  } else if (text === undefined) {
116	    errors.push({ field: 'body', message: 'body is too large' });
117	  } else {
118	    let parsed: unknown;
119	    try {
120	      parsed = JSON.parse(text);
121	    } catch {
122	      errors.push({ field: 'body', message: 'is not valid JSON' });
123	    }
124	    if (errors.length === 0) values = validateBody(parsed, errors);
125	  }
126	
127	  const keyHeader = req.headers['idempotency-key'];
128	  let idemKey: string | null = null;
129	  if (keyHeader !== undefined) {
130	    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY.test(keyHeader)) idemKey = keyHeader;
131	    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
132	  }
133	
134	  if (errors.length > 0 || !values) {
135	    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
136	    return;
137	  }
138	
139	  const fingerprint = JSON.stringify([values.input, values.steps, values.failAttempts]);
140	  if (idemKey !== null) {
141	    const existing = selectByKey.get(idemKey) as unknown as JobRow | undefined;
142	    if (existing) {
143	      if (existing.fingerprint === fingerprint) send(res, 200, toJob(existing));
144	      else sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
145	      return;
146	    }
147	  }
148	
149	  const id = randomUUID();
150	  const now = new Date().toISOString();
151	  insertJob.run(id, values.input, values.steps, values.failAttempts, idemKey, idemKey === null ? null : fingerprint, now, now);
152	  const row = selectById.get(id) as unknown as JobRow;
153	  send(res, 201, toJob(row));
154	}
155	
156	function health(res: ServerResponse): void {
157	  const hb = selectHeartbeat.get() as unknown as { at_ms: number } | undefined;
158	  const up = hb !== undefined && Date.now() - Number(hb.at_ms) <= WORKER_STALE_MS;
159	  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
160	}
161	
162	function methodNotAllowed(res: ServerResponse, allow: string): void {
163	  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
164	}
165	
166	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
167	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
168	  const method = req.method ?? 'GET';
169	
170	  if (pathname === '/health') {
171	    if (method === 'GET') return health(res);
172	    return methodNotAllowed(res, 'GET');
173	  }
174	  if (pathname === '/') {
175	    if (method !== 'GET') return methodNotAllowed(res, 'GET');
176	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
177	    res.end(uiHtml);
178	    return;
179	  }
180	  if (pathname === '/api/jobs') {
181	    if (method === 'GET') {
182	      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
183	      return send(res, 200, { jobs });
184	    }
185	    if (method === 'POST') return createJob(req, res);
186	    return methodNotAllowed(res, 'GET, POST');
187	  }
188	  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
189	  if (match) {
190	    if (method !== 'GET') return methodNotAllowed(res, 'GET');
191	    const row = selectById.get(match[1]!) as unknown as JobRow | undefined;
192	    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
193	    return send(res, 200, toJob(row));
194	  }
195	  sendError(res, 404, 'not_found', 'Not found.');
196	}
197	
198	const port = Number(process.env.PORT ?? 3000);
199	const server = createServer((req, res) => {
200	  handle(req, res).catch((e: unknown) => {
201	    console.error(e);
202	    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
203	    else res.end();
204	  });
205	});
206	
207	function shutdown(): void {
208	  server.close(() => {
209	    db.close();
210	    process.exit(0);
211	  });
212	  server.closeAllConnections();
213	  setTimeout(() => process.exit(0), 3_000).unref();
214	}
215	process.on('SIGTERM', shutdown);
216	process.on('SIGINT', shutdown);
217	
218	server.listen(port, () => console.log(`server listening on ${port}`));
