import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, type JobRow } from './db.ts';

const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const FIELD_NAMES = ['input', 'steps', 'failAttempts'];

interface FieldError {
  field: string;
  message: string;
}

interface JobInput {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, fingerprint, available_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare("SELECT at_ms FROM heartbeat WHERE name = 'worker'");

function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, headers);
}

function intField(obj: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, errors: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a parsed request body. Returns undefined when the body is not an object (an error is recorded). */
function validateBody(raw: unknown, errors: FieldError[]): JobInput | undefined {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    errors.push({ field: 'body', message: 'must be a JSON object' });
    return undefined;
  }
  const obj = raw as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!FIELD_NAMES.includes(key)) errors.push({ field: key, message: 'is not a recognised field' });
  }
  let input = '';
  const rawInput = obj.input;
  if (typeof rawInput !== 'string') errors.push({ field: 'input', message: 'is required and must be a string' });
  else if (rawInput.length < 1 || rawInput.length > 1000) errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  else if (rawInput.trim() === '') errors.push({ field: 'input', message: 'must not be only whitespace' });
  else input = rawInput;
  const steps = intField(obj, 'steps', 1, 20, 5, errors);
  const failAttempts = intField(obj, 'failAttempts', 0, 5, 0, errors);
  return { input, steps, failAttempts };
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const text = await readBody(req);

  const mediaType = req.headers['content-type']?.split(';')[0]?.trim().toLowerCase();
  let values: JobInput | undefined;
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (text === undefined) {
    errors.push({ field: 'body', message: 'body is too large' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      errors.push({ field: 'body', message: 'is not valid JSON' });
    }
    if (errors.length === 0) values = validateBody(parsed, errors);
  }

  const keyHeader = req.headers['idempotency-key'];
  let idemKey: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY.test(keyHeader)) idemKey = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (errors.length > 0 || !values) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const fingerprint = JSON.stringify([values.input, values.steps, values.failAttempts]);
  if (idemKey !== null) {
    const existing = selectByKey.get(idemKey) as unknown as JobRow | undefined;
    if (existing) {
      if (existing.fingerprint === fingerprint) send(res, 200, toJob(existing));
      else sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      return;
    }
  }

  const id = randomUUID();
  const now = new Date().toISOString();
  insertJob.run(id, values.input, values.steps, values.failAttempts, idemKey, idemKey === null ? null : fingerprint, now, now);
  const row = selectById.get(id) as unknown as JobRow;
  send(res, 201, toJob(row));
}

function health(res: ServerResponse): void {
  const hb = selectHeartbeat.get() as unknown as { at_ms: number } | undefined;
  const up = hb !== undefined && Date.now() - Number(hb.at_ms) <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method === 'GET') return health(res);
    return methodNotAllowed(res, 'GET');
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const row = selectById.get(match[1]!) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error(e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

